package com.example.resumescanner.util; import org.springframework.web.multipart.MultipartFile; import java.io.*; public class ResumeParser{ public static String extractText(MultipartFile f)throws Exception{ BufferedReader r=new BufferedReader(new InputStreamReader(f.getInputStream())); StringBuilder sb=new StringBuilder(); String l; while((l=r.readLine())!=null){ sb.append(l).append(" "); } return sb.toString(); } }